// App.js
import React, { useState, useEffect, useRef } from 'react';
import * as XLSX from 'xlsx';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  Cell
} from 'recharts';
import './App.css';

// קומפוננטת גרף עמודות אופקיות (לרוחב)
const HorizontalBarChart = ({ data, dataKey, nameKey, title, colors, isStacked = false, stackedKeys = [] }) => {
  // וידוא שיש נתונים לתצוגה
  if (!data || data.length === 0 || 
      (isStacked && (!stackedKeys || stackedKeys.length === 0)) || 
      (!isStacked && !dataKey)) {
    return (
      <div className="chart-container">
        <h3 className="chart-title">{title}</h3>
        <div className="no-data-message">אין נתונים זמינים להצגה</div>
      </div>
    );
  }

  return (
    <div className="chart-container">
      <h3 className="chart-title">{title}</h3>
      <ResponsiveContainer width="100%" height={400}>
        <BarChart 
          data={data} 
          layout="vertical"
          margin={{ top: 20, right: 30, left: 50, bottom: 5 }}
        >
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis type="number" />
          <YAxis 
            dataKey={nameKey} 
            type="category" 
            width={120} 
            tick={{ fill: '#495057' }} 
          />
          <Tooltip 
            formatter={(value) => new Intl.NumberFormat('he-IL').format(value) + ' ₪'} 
            contentStyle={{ textAlign: 'right', direction: 'rtl' }}
          />
          <Legend 
            layout="vertical" 
            align="left"
            verticalAlign="middle"
            wrapperStyle={{ left: 0, paddingRight: '20px', direction: 'rtl', textAlign: 'right' }}
          />
          {!isStacked ? (
            <Bar dataKey={dataKey} name={dataKey}>
              {data.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={colors[index % colors.length]} />
              ))}
            </Bar>
          ) : (
            stackedKeys.map((key, index) => (
              <Bar key={key} dataKey={key} name={key} fill={colors[index % colors.length]} />
            ))
          )}
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

// קומפוננטה לטבלה עם אפשרות מיון
const SortableTable = ({ data, columns, title, formatNumber = (num) => num, showTotals = true }) => {
  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'asc' });
  const tableRef = useRef(null);

  // מיון הנתונים
  const requestSort = (key) => {
    let direction = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  // סידור הנתונים לפי המיון הנבחר
  const sortedData = React.useMemo(() => {
    let sortableItems = [...data];
    if (sortConfig.key) {
      sortableItems.sort((a, b) => {
        if (a[sortConfig.key] === null || a[sortConfig.key] === undefined) return 1;
        if (b[sortConfig.key] === null || b[sortConfig.key] === undefined) return -1;
        
        const aValue = typeof a[sortConfig.key] === 'string' ? a[sortConfig.key].toLowerCase() : a[sortConfig.key];
        const bValue = typeof b[sortConfig.key] === 'string' ? b[sortConfig.key].toLowerCase() : b[sortConfig.key];
        
        if (aValue < bValue) {
          return sortConfig.direction === 'asc' ? -1 : 1;
        }
        if (aValue > bValue) {
          return sortConfig.direction === 'asc' ? 1 : -1;
        }
        return 0;
      });
    }
    return sortableItems;
  }, [data, sortConfig]);

  // חישוב סיכומים
  const totals = React.useMemo(() => {
    const totalsObj = {};
    columns.forEach(column => {
      if (column.isNumeric) {
        totalsObj[column.key] = data.reduce((sum, item) => {
          return sum + (item[column.key] || 0);
        }, 0);
      }
    });
    return totalsObj;
  }, [data, columns]);

  // סמן לכיוון המיון
  const getSortDirectionIndicator = (key) => {
    if (sortConfig.key !== key) return null;
    return sortConfig.direction === 'asc' ? ' ▲' : ' ▼';
  };

  return (
    <div className="table-container">
      <h2 className="table-title">{title}</h2>
      <div className="table-wrapper" ref={tableRef}>
        <table className="data-table">
          <thead>
            <tr>
              {columns.map(column => (
                <th 
                  key={column.key}
                  className={`table-header ${column.wide ? 'wide-column' : ''} ${column.sticky ? 'sticky-column' : ''}`}
                  onClick={() => column.sortable !== false && requestSort(column.key)}
                >
                  {column.label}
                  {column.sortable !== false && getSortDirectionIndicator(column.key)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {sortedData.map((item, index) => (
              <tr key={index} className={index % 2 === 0 ? 'row-even' : 'row-odd'}>
                {columns.map(column => (
                  <td 
                    key={`${index}-${column.key}`} 
                    className={`table-cell ${column.sticky ? 'sticky-column' : ''}`}
                  >
                    {column.render 
                      ? column.render(item[column.key], item) 
                      : column.isNumeric && item[column.key] !== null
                        ? formatNumber(item[column.key]) + (column.unit || '')
                        : item[column.key] || '-'}
                  </td>
                ))}
              </tr>
            ))}
            {sortedData.length === 0 && (
              <tr>
                <td colSpan={columns.length} className="table-cell empty-message">
                  לא נמצאו נתונים
                </td>
              </tr>
            )}
            {showTotals && sortedData.length > 0 && (
              <tr className="total-row">
                {columns.map((column, index) => (
                  <td 
                    key={`total-${column.key}`} 
                    className={`table-cell total-cell ${column.sticky ? 'sticky-column' : ''}`}
                  >
                    {index === 0 ? (
                      <strong>סה"כ</strong>
                    ) : column.isNumeric ? (
                      <strong>
                        {column.render 
                          ? column.render(totals[column.key], { isTotalRow: true }) 
                          : formatNumber(totals[column.key]) + (column.unit || '')}
                      </strong>
                    ) : null}
                  </td>
                ))}
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

// קומפוננטה לטבלה מרוכזת עם כותרות קבוצתיות
const GroupedTable = ({ data, years, title, formatNumber = (num) => num, type }) => {
  // ארגון נתונים לפי מוסדות
  const institutionData = React.useMemo(() => {
    const result = {};

    // קביעת השדות בהתאם לסוג הטבלה
    let fields = [];
    switch (type) {
      case 'participation':
        fields = [
          { key: 'agreementParticipation', label: 'השתתפות ע"פ הסכם' },
          { key: 'approvedParticipation', label: 'השתתפות מאושרת' },
          { key: 'finalParticipation', label: 'השתתפות סופית' }
        ];
        break;
      case 'construction':
        fields = [
          { key: 'totalCost', label: 'עלות פרויקט' },
          { key: 'initialParticipation', label: 'השתתפות ראשונית' },
          { key: 'currentParticipation', label: 'השתתפות נכון ל-1.5.25' }
        ];
        break;
      case 'loans':
        fields = [
          { key: 'amount', label: 'סכום הלוואה' },
          { key: 'repayment', label: 'החזר' }
        ];
        break;
      default:
        break;
    }

    // איסוף כל המוסדות
    let institutions = {};
    data.forEach(item => {
      const institutionName = type === 'participation' ? item.name : 
                              type === 'construction' ? item.institution : 
                              item.institution;
      
      if (!institutions[institutionName]) {
        institutions[institutionName] = true;
      }
    });

    // יצירת נתונים מרוכזים
    Object.keys(institutions).forEach(institutionName => {
      result[institutionName] = { name: institutionName };
      
      // איסוף הערות מכל השנים
      let notes = [];
      
      // איסוף נתונים לפי שנים
      years.forEach(year => {
        // מציאת פריטים מתאימים
        const yearItems = data.filter(item => {
          const itemYear = item.year;
          const itemInstitution = type === 'participation' ? item.name : 
                                 type === 'construction' ? item.institution : 
                                 item.institution;
          return itemYear === year && itemInstitution === institutionName;
        });
        
        if (yearItems.length > 0) {
          fields.forEach(field => {
            result[institutionName][`${year}_${field.key}`] = yearItems[0][field.key];
          });
          
          // הוספת הערות אם קיימות
          if (yearItems[0].notes && yearItems[0].notes.trim()) {
            notes.push(`(${year}) ${yearItems[0].notes}`);
          }
        }
      });
      
      // הוספת הערות מאוחדות
      if (notes.length > 0) {
        result[institutionName].notes = notes.join(' | ');
      }
    });

    return Object.values(result);
  }, [data, years, type]);

  // יצירת עמודות לפי השנים - בפורמט קבוצתי
  const columns = React.useMemo(() => {
    const cols = [
      { key: 'name', label: 'שם מוסד', sortable: true, wide: true, sticky: true }
    ];

    let yearFields = [];
    switch (type) {
      case 'participation':
        yearFields = [
          { key: 'agreementParticipation', label: 'השתתפות ע"פ הסכם', isNumeric: true },
          { key: 'approvedParticipation', label: 'השתתפות מאושרת', isNumeric: true },
          { key: 'finalParticipation', label: 'השתתפות סופית', isNumeric: true }
        ];
        break;
      case 'construction':
        yearFields = [
          { key: 'totalCost', label: 'עלות פרויקט', isNumeric: true },
          { key: 'initialParticipation', label: 'השתתפות ראשונית', isNumeric: true },
          { key: 'currentParticipation', label: 'השתתפות נכון ל-1.5.25', isNumeric: true }
        ];
        break;
      case 'loans':
        yearFields = [
          { key: 'amount', label: 'סכום הלוואה', isNumeric: true },
          { key: 'repayment', label: 'החזר', isNumeric: false }
        ];
        break;
      default:
        break;
    }

    // הוספת השדות לפי שנה
    years.forEach(year => {
      yearFields.forEach(field => {
        cols.push({
          key: `${year}_${field.key}`,
          label: field.label,
          group: year,
          sortable: true,
          isNumeric: field.isNumeric,
          render: value => (field.isNumeric && value) ? formatNumber(value) + ' ₪' : value || '-'
        });
      });
    });

    // הוספת עמודת הערות
    cols.push({ key: 'notes', label: 'הערות', sortable: true, wide: true });

    return cols;
  }, [years, type, formatNumber]);

  // מידע לכותרות קבוצתיות
  const columnGroups = React.useMemo(() => {
    const groups = new Map();
    
    columns.forEach(col => {
      if (col.group) {
        if (!groups.has(col.group)) {
          groups.set(col.group, { label: col.group, count: 0 });
        }
        groups.get(col.group).count++;
      }
    });
    
    return groups;
  }, [columns]);

  // חישוב סיכומים לפי כל השדות המספריים
  const totals = React.useMemo(() => {
    const totalsObj = {};
    
    columns.forEach(column => {
      if (column.isNumeric) {
        totalsObj[column.key] = institutionData.reduce((sum, item) => {
          return sum + (item[column.key] || 0);
        }, 0);
      }
    });
    
    return totalsObj;
  }, [institutionData, columns]);

  return (
    <div className="table-container full-width">
      <h2 className="table-title">{title}</h2>
      <div className="table-wrapper">
        <table className="data-table grouped-table">
          <thead>
            {/* שורת כותרות קבוצתיות */}
            <tr className="group-header-row">
              {/* תא ריק מעל עמודת שם מוסד */}
              <th className="group-header sticky-column"></th>
              
              {/* כותרות קבוצתיות לפי שנים */}
              {Array.from(columnGroups.entries()).map(([groupName, group]) => (
                <th 
                  key={groupName} 
                  colSpan={group.count} 
                  className="group-header"
                >
                  {groupName}
                </th>
              ))}
              
              {/* תא ריק מעל עמודת הערות */}
              <th className="group-header"></th>
            </tr>
            
            {/* שורת כותרות עמודות */}
            <tr>
              {columns.map(column => (
                <th 
                  key={column.key}
                  className={`table-header ${column.wide ? 'wide-column' : ''} ${column.sticky ? 'sticky-column' : ''}`}
                >
                  {column.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {institutionData.map((item, index) => (
              <tr key={index} className={index % 2 === 0 ? 'row-even' : 'row-odd'}>
                {columns.map(column => (
                  <td 
                    key={`${index}-${column.key}`} 
                    className={`table-cell ${column.sticky ? 'sticky-column' : ''}`}
                  >
                    {column.render 
                      ? column.render(item[column.key], item) 
                      : column.isNumeric && item[column.key] !== null
                        ? formatNumber(item[column.key]) + (column.unit || '')
                        : item[column.key] || '-'}
                  </td>
                ))}
              </tr>
            ))}
            {institutionData.length === 0 && (
              <tr>
                <td colSpan={columns.length} className="table-cell empty-message">
                  לא נמצאו נתונים
                </td>
              </tr>
            )}
            {/* שורת סיכום */}
            {institutionData.length > 0 && (
              <tr className="total-row">
                {columns.map((column, index) => (
                  <td 
                    key={`total-${column.key}`} 
                    className={`table-cell total-cell ${column.sticky ? 'sticky-column' : ''}`}
                  >
                    {index === 0 ? (
                      <strong>סה"כ</strong>
                    ) : column.isNumeric ? (
                      <strong>
                        {column.render 
                          ? column.render(totals[column.key], { isTotalRow: true }) 
                          : formatNumber(totals[column.key]) + (column.unit || '')}
                      </strong>
                    ) : null}
                  </td>
                ))}
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

