// קומפוננט הדשבורד
const FinancialDashboard = () => {
  const [activeTab, setActiveTab] = useState('participation');
  const [data, setData] = useState({
    participation: { byYear: {}, institutions: [] },
    construction: { byYear: {}, projects: [] },
    loans: { byYear: {}, loansList: [] }
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [fileUploaded, setFileUploaded] = useState(false);
  const [summaryData, setSummaryData] = useState({
    totalParticipation: 0,
    totalConstruction: 0,
    totalLoans: 0
  });

  // צבעים מהלוגו
  const logoColors = ['#0078b6', '#8e489b', '#a2ca43', '#00a4e4'];
  // קבועים למחרוזות עם גרשיים
  const loansAmountKey = 'סה"כ הלוואות';
  
  // שנים שזמינות בנתונים
  const [availableYears, setAvailableYears] = useState([]);

  // פונקציה לטעינת הקובץ
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setLoading(true);
    setError(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        
        processExcelData(workbook);
        setFileUploaded(true);
      } catch (err) {
        console.error("Error processing file:", err);
        setError("אירעה שגיאה בעיבוד הקובץ: " + err.message);
      } finally {
        setLoading(false);
      }
    };
    
    reader.onerror = (event) => {
      setError("אירעה שגיאה בקריאת הקובץ");
      setLoading(false);
    };
    
    reader.readAsArrayBuffer(file);
  };

  // פונקציה לעיבוד נתוני האקסל
  const processExcelData = (workbook) => {
    // Parse participation data
    const participationSheet = workbook.Sheets["השתתפות מרכז בשוטף"];
    if (!participationSheet) {
      setError("גיליון 'השתתפות מרכז בשוטף' לא נמצא בקובץ");
      return;
    }

    const participationData = XLSX.utils.sheet_to_json(participationSheet, {
      header: 1,
      defval: null,
      blankrows: false
    });
    
    // Parse construction data
    const constructionSheet = workbook.Sheets["בינוי "];
    if (!constructionSheet) {
      setError("גיליון 'בינוי ' לא נמצא בקובץ");
      return;
    }

    const constructionData = XLSX.utils.sheet_to_json(constructionSheet, {
      header: 1,
      defval: null,
      blankrows: false
    });
    
    // Parse loans data
    const loanSheet = workbook.Sheets["הלוואת בעלות"];
    if (!loanSheet) {
      setError("גיליון 'הלוואת בעלות' לא נמצא בקובץ");
      return;
    }

    const loanData = XLSX.utils.sheet_to_json(loanSheet, {
      header: 1,
      defval: null,
      blankrows: false
    });

    // איסוף כל השנים הזמינות
    const yearsSet = new Set();

    // Process participation data
    const participationByYear = {};
    const institutions = [];
    let totalFinalParticipation = 0;
    
    participationData.forEach((row, index) => {
      if (index === 0) return; // Skip header
      
      const year = row[0];
      if (!year || typeof year !== 'string' || !year.includes("תשפ")) return;
      
      // הוספת השנה לרשימת השנים
      yearsSet.add(year);
      
      if (!participationByYear[year]) {
        participationByYear[year] = {
          agreementSum: 0,
          approvedSum: 0,
          finalSum: 0,
          count: 0
        };
      }
      
      participationByYear[year].count++;
      
      if (row[2] && !isNaN(row[2])) participationByYear[year].agreementSum += row[2];
      if (row[3] && !isNaN(row[3])) participationByYear[year].approvedSum += row[3];
      if (row[4] && !isNaN(row[4])) {
        participationByYear[year].finalSum += row[4];
        totalFinalParticipation += row[4];
      }
      
      institutions.push({
        year: year,
        name: row[1],
        agreementParticipation: row[2],
        approvedParticipation: row[3],
        finalParticipation: row[4],
        notes: row[5]
      });
    });
    
    // Process construction data
    const constructionByYear = {};
    const projects = [];
    let totalConstructionParticipation = 0;
    
    constructionData.forEach((row, index) => {
      if (index === 0) return; // Skip header
      
      const year = row[0];
      if (!year || typeof year !== 'string' || !year.includes("תשפ")) return;
      
      // הוספת השנה לרשימת השנים
      yearsSet.add(year);
      
      if (!constructionByYear[year]) {
        constructionByYear[year] = {
          totalCost: 0,
          initialParticipation: 0,
          currentParticipation: 0,
          count: 0
        };
      }
      
      constructionByYear[year].count++;
      
      if (row[3] && !isNaN(row[3])) constructionByYear[year].totalCost += row[3];
      if (row[4] && !isNaN(row[4])) constructionByYear[year].initialParticipation += row[4];
      if (row[5] && !isNaN(row[5])) {
        constructionByYear[year].currentParticipation += row[5];
        totalConstructionParticipation += row[5];
      }
      
      projects.push({
        year: year,
        institution: row[1],
        projectType: row[2],
        totalCost: row[3],
        initialParticipation: row[4],
        currentParticipation: row[5],
        notes: row[6]
      });
    });
    
    // Process loans data
    const loansByYear = {};
    const loansList = [];
    let totalLoansAmount = 0;
    
    // Find header row
    let headerRowIndex = loanData.findIndex(row => row[0] === "שנה");
    
    if (headerRowIndex >= 0) {
      for (let i = headerRowIndex + 1; i < loanData.length; i++) {
        const row = loanData[i];
        if (!row[0]) continue;
        
        const year = row[0];
        if (!year || typeof year !== 'string' || !year.includes("תשפ")) continue;
        
        // הוספת השנה לרשימת השנים
        yearsSet.add(year);
        
        if (!loansByYear[year]) {
          loansByYear[year] = {
            totalAmount: 0,
            count: 0
          };
        }
        
        loansByYear[year].count++;
        if (row[3] && !isNaN(row[3])) {
          loansByYear[year].totalAmount += row[3];
          totalLoansAmount += row[3];
        }
        
        loansList.push({
          year: year,
          institution: row[1],
          loanType: row[2],
          amount: row[3],
          repayment: row[4]
        });
      }
    }

    // עדכון רשימת השנים הזמינות
    setAvailableYears(Array.from(yearsSet).sort());

    // עדכון נתוני סיכום
    setSummaryData({
      totalParticipation: totalFinalParticipation,
      totalConstruction: totalConstructionParticipation,
      totalLoans: totalLoansAmount
    });

    setData({
      participation: { 
        byYear: participationByYear, 
        institutions 
      },
      construction: { 
        byYear: constructionByYear, 
        projects 
      },
      loans: { 
        byYear: loansByYear, 
        loansList 
      }
    });
  };

  // פונקציה להכנת נתונים לגרפים
  const prepareChartData = () => {
    // מציאת השנה האחרונה (תשפ"ה או בהתאם לנתונים)
    const latestYear = availableYears.length > 0 ? 
      availableYears[availableYears.length - 1] : null;
    
    const previousYear = availableYears.length > 1 ? 
      availableYears[availableYears.length - 2] : null;

    // השתתפויות לפי שנים
    const participationYearData = Object.keys(data.participation.byYear).map(year => ({
      name: year,
      'השתתפות ע"פ הסכם': data.participation.byYear[year].agreementSum,
      'השתתפות מאושרת': data.participation.byYear[year].approvedSum,
      'השתתפות סופית': data.participation.byYear[year].finalSum,
    })).sort((a, b) => b.name.localeCompare(a.name)); // מיון הפוך כדי שהשנים האחרונות יהיו למעלה

    // השתתפויות בינוי לפי שנים
    const constructionYearData = Object.keys(data.construction.byYear).map(year => ({
      name: year,
      'סה"כ עלות': data.construction.byYear[year].totalCost,
      'השתתפות ראשונית': data.construction.byYear[year].initialParticipation,
      'השתתפות נוכחית': data.construction.byYear[year].currentParticipation,
    })).sort((a, b) => b.name.localeCompare(a.name));

    // הלוואות לפי שנים
    const loansYearData = Object.keys(data.loans.byYear).map(year => ({
      name: year,
      [loansAmountKey]: data.loans.byYear[year].totalAmount,
    })).sort((a, b) => b.name.localeCompare(a.name));

    // גרף השתתפויות לפי מוסדות בשנה האחרונה
    const latestYearInstitutions = latestYear ? 
      data.participation.institutions
        .filter(item => item.year === latestYear)
        .map(item => ({
          name: item.name,
          'השתתפות ע"פ הסכם': item.agreementParticipation || 0,
          'השתתפות מאושרת': item.approvedParticipation || 0,
          'השתתפות סופית': item.finalParticipation || 0
        }))
        .sort((a, b) => (b['השתתפות סופית'] || 0) - (a['השתתפות סופית'] || 0))
        .slice(0, 10) : [];

    // גרף בינוי לפי מוסדות בשנתיים האחרונות
    const recentConstructionData = [];
    if (latestYear) {
      // מוסדות בשנתיים האחרונות
      const relevantProjects = data.construction.projects
        .filter(item => item.year === latestYear || (previousYear && item.year === previousYear));
      
      // קבוצות מוסדות לפי שם
      const groupedByInstitution = {};
      
      relevantProjects.forEach(project => {
        if (!groupedByInstitution[project.institution]) {
          groupedByInstitution[project.institution] = {};
        }
        
        if (!groupedByInstitution[project.institution][project.year]) {
          groupedByInstitution[project.institution][project.year] = 0;
        }
        
        groupedByInstitution[project.institution][project.year] += (project.currentParticipation || 0);
      });
      
      // יצירת נתונים לגרף
      Object.keys(groupedByInstitution).forEach(institution => {
        const institutionData = { 
          name: institution,
          [latestYear]: groupedByInstitution[institution][latestYear] || 0
        };
        
        if (previousYear) {
          institutionData[previousYear] = groupedByInstitution[institution][previousYear] || 0;
        }
        
        recentConstructionData.push(institutionData);
      });
      
      // מיון לפי השנה האחרונה
      recentConstructionData.sort((a, b) => b[latestYear] - a[latestYear]);
    }

    // גרף הלוואות לפי מוסדות בשנתיים האחרונות
    const recentLoansData = [];
    if (latestYear) {
      // מוסדות בשנתיים האחרונות
      const relevantLoans = data.loans.loansList
        .filter(item => item.year === latestYear || (previousYear && item.year === previousYear));
      
      // קבוצות מוסדות לפי שם
      const groupedByInstitution = {};
      
      relevantLoans.forEach(loan => {
        if (!groupedByInstitution[loan.institution]) {
          groupedByInstitution[loan.institution] = {};
        }
        
        if (!groupedByInstitution[loan.institution][loan.year]) {
          groupedByInstitution[loan.institution][loan.year] = 0;
        }
        
        groupedByInstitution[loan.institution][loan.year] += (loan.amount || 0);
      });
      
      // יצירת נתונים לגרף
      Object.keys(groupedByInstitution).forEach(institution => {
        const institutionData = { 
          name: institution,
          [latestYear]: groupedByInstitution[institution][latestYear] || 0
        };
        
        if (previousYear) {
          institutionData[previousYear] = groupedByInstitution[institution][previousYear] || 0;
        }
        
        recentLoansData.push(institutionData);
      });
      
      // מיון לפי השנה האחרונה
      recentLoansData.sort((a, b) => b[latestYear] - a[latestYear]);
    }

    return {
      participationYearData,
      constructionYearData,
      loansYearData,
      latestYearInstitutions,
      recentConstructionData,
      recentLoansData,
      latestYear,
      previousYear
    };
  };

  // פונקציה לעיצוב מספרים
  const formatNumber = (num) => {
    if (num === null || num === undefined) return '-';
    return new Intl.NumberFormat('he-IL').format(num);
  };

  // הכנת נתוני גרפים
  const chartData = fileUploaded ? prepareChartData() : null;

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <h1 className="dashboard-title">דשבורד נתונים פיננסיים</h1>
      </header>
      
      {/* טעינת קובץ */}
      <div className="file-upload-section">
        <label htmlFor="excel-file" className="file-upload-label">
          בחר/י קובץ אקסל:
          <input
            type="file"
            id="excel-file"
            accept=".xlsx,.xls"
            onChange={handleFileUpload}
            className="file-input"
          />
        </label>
        <div className="file-status">
          {loading && <p className="loading-message">טוען נתונים...</p>}
          {error && <p className="error-message">{error}</p>}
          {fileUploaded && <p className="success-message">הקובץ נטען בהצלחה!</p>}
        </div>
      </div>
      
      {fileUploaded && (
        <>
          {/* כרטיסי סיכום */}
          <div className="summary-cards">
            <SummaryCard 
              title="סה״כ השתתפות מרכז" 
              value={formatNumber(summaryData.totalParticipation) + " ₪"}
              icon="₪"
              color={logoColors[0]}
            />
            <SummaryCard 
              title="סה״כ בינוי" 
              value={formatNumber(summaryData.totalConstruction) + " ₪"}
              icon="₪"
              color={logoColors[1]}
            />
            <SummaryCard 
              title="סה״כ הלוואות" 
              value={formatNumber(summaryData.totalLoans) + " ₪"}
              icon="₪"
              color={logoColors[2]}
            />
          </div>

          {/* Tabs */}
          <div className="tabs-container">
            <button 
              className={`tab-button ${activeTab === 'participation' ? 'active-tab' : ''}`}
              onClick={() => setActiveTab('participation')}
              style={{ borderColor: activeTab === 'participation' ? logoColors[0] : 'transparent' }}
            >
              השתתפות מרכז בשוטף
            </button>
            <button 
              className={`tab-button ${activeTab === 'construction' ? 'active-tab' : ''}`}
              onClick={() => setActiveTab('construction')}
              style={{ borderColor: activeTab === 'construction' ? logoColors[1] : 'transparent' }}
            >
              בינוי
            </button>
            <button 
              className={`tab-button ${activeTab === 'loans' ? 'active-tab' : ''}`}
              onClick={() => setActiveTab('loans')}
              style={{ borderColor: activeTab === 'loans' ? logoColors[2] : 'transparent' }}
            >
              הלוואות בעלות
            </button>
          </div>
          
          {/* תוכן לפי טאב */}
          {activeTab === 'participation' && (
            <div className="tab-content">
              {/* תצוגת גרפים */}
              <div className="charts-row">
                <HorizontalBarChart 
                  data={chartData.participationYearData}
                  nameKey="name"
                  isStacked={true}
                  stackedKeys={['השתתפות ע"פ הסכם', 'השתתפות מאושרת', 'השתתפות סופית']}
                  title="השתתפויות לפי שנים"
                  colors={logoColors}
                />
                
                {chartData.latestYear && chartData.latestYearInstitutions && chartData.latestYearInstitutions.length > 0 && (
                  <HorizontalBarChart 
                    data={chartData.latestYearInstitutions.slice(0, 10)}
                    nameKey="name"
                    isStacked={true}
                    stackedKeys={['השתתפות ע"פ הסכם', 'השתתפות מאושרת', 'השתתפות סופית']}
                    title={`השתתפויות לפי מוסדות - ${chartData.latestYear}`}
                    colors={logoColors}
                  />
                )}
              </div>

              {/* טבלה מרוכזת לפי מוסדות ושנים */}
              <GroupedTable 
                data={data.participation.institutions}
                years={availableYears}
                title="טבלה מרוכזת - השתתפויות לפי מוסדות ושנים"
                formatNumber={formatNumber}
                type="participation"
              />

              {/* טבלת סיכום */}
              <SortableTable
                title="סיכום השתתפות לפי שנים"
                data={Object.keys(data.participation.byYear).map(year => ({
                  year,
                  count: data.participation.byYear[year].count,
                  agreementSum: data.participation.byYear[year].agreementSum,
                  approvedSum: data.participation.byYear[year].approvedSum,
                  finalSum: data.participation.byYear[year].finalSum
                }))}
                formatNumber={formatNumber}
                columns={[
                  { key: 'year', label: 'שנה', sortable: true, sticky: true },
                  { key: 'count', label: 'מספר מוסדות', sortable: true, isNumeric: true },
                  { 
                    key: 'agreementSum', 
                    label: 'השתתפות ע"פ הסכם', 
                    sortable: true, 
                    isNumeric: true,
                    render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                  },
                  { 
                    key: 'approvedSum', 
                    label: 'השתתפות מאושרת', 
                    sortable: true, 
                    isNumeric: true,
                    render: (value) => value ? formatNumber(value) + ' ₪' : '-'  
                  },
                  { 
                    key: 'finalSum', 
                    label: 'השתתפות סופית', 
                    sortable: true, 
                    isNumeric: true,
                    render: (value) => value ? formatNumber(value) + ' ₪' : '-'  
                  }
                ]}
              />

              {/* טבלות לפי שנים */}
              {Object.keys(data.participation.byYear).map(year => (
                <SortableTable
                  key={year}
                  title={`${year} - פירוט השתתפות לפי מוסדות`}
                  data={data.participation.institutions.filter(inst => inst.year === year)}
                  formatNumber={formatNumber}
                  columns={[
                    { key: 'name', label: 'שם מוסד', sortable: true, sticky: true },
                    { 
                      key: 'agreementParticipation', 
                      label: 'השתתפות ע"פ הסכם', 
                      sortable: true,
                      isNumeric: true,
                      render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                    },
                    { 
                      key: 'approvedParticipation', 
                      label: 'השתתפות מאושרת', 
                      sortable: true,
                      isNumeric: true,
                      render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                    },
                    { 
                      key: 'finalParticipation', 
                      label: 'השתתפות סופית', 
                      sortable: true,
                      isNumeric: true,
                      render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                    },
                    { key: 'notes', label: 'הערות', sortable: true }
                  ]}
                />
              ))}
            </div>
          )}
          
          {/* תצוגת נתוני בינוי */}
          {activeTab === 'construction' && (
            <div className="tab-content">
              {/* תצוגת גרפים */}
              <div className="charts-row">
                <HorizontalBarChart 
                  data={chartData.constructionYearData}
                  nameKey="name"
                  isStacked={true}
                  stackedKeys={['סה"כ עלות', 'השתתפות ראשונית', 'השתתפות נוכחית']}
                  title="פרויקטי בינוי לפי שנים"
                  colors={logoColors}
                />
                
                {chartData.recentConstructionData && chartData.recentConstructionData.length > 0 && (
                  <HorizontalBarChart 
                    data={chartData.recentConstructionData.slice(0, 10)}
                    nameKey="name"
                    isStacked={true}
                    stackedKeys={availableYears.slice(-2)}
                    title={`פרויקטי בינוי לפי מוסדות - ${availableYears.slice(-2).join(', ')}`}
                    colors={[logoColors[1], logoColors[3]]}
                  />
                )}
              </div>

              {/* טבלה מרוכזת לפי מוסדות ושנים */}
              <GroupedTable 
                data={data.construction.projects}
                years={availableYears}
                title="טבלה מרוכזת - פרויקטי בינוי לפי מוסדות ושנים"
                formatNumber={formatNumber}
                type="construction"
              />

              {/* טבלת סיכום */}
              <SortableTable
                title="סיכום פרויקטי בינוי לפי שנים"
                data={Object.keys(data.construction.byYear).map(year => ({
                  year,
                  count: data.construction.byYear[year].count,
                  totalCost: data.construction.byYear[year].totalCost,
                  initialParticipation: data.construction.byYear[year].initialParticipation,
                  currentParticipation: data.construction.byYear[year].currentParticipation
                }))}
                formatNumber={formatNumber}
                columns={[
                  { key: 'year', label: 'שנה', sortable: true, sticky: true },
                  { key: 'count', label: 'מספר פרויקטים', sortable: true, isNumeric: true },
                  { 
                    key: 'totalCost', 
                    label: 'סה"כ עלות פרויקטים', 
                    sortable: true, 
                    isNumeric: true,
                    render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                  },
                  { 
                    key: 'initialParticipation', 
                    label: 'השתתפות רשת ראשונית', 
                    sortable: true, 
                    isNumeric: true,
                    render: (value) => value ? formatNumber(value) + ' ₪' : '-'  
                  },
                  { 
                    key: 'currentParticipation', 
                    label: 'השתתפות רשת נכון ל-1.5.25', 
                    sortable: true, 
                    isNumeric: true,
                    render: (value) => value ? formatNumber(value) + ' ₪' : '-'  
                  }
                ]}
              />
              
              {/* טבלות לפי שנים */}
              {Object.keys(data.construction.byYear).map(year => (
                <SortableTable
                  key={year}
                  title={`${year} - פירוט פרויקטי בינוי`}
                  data={data.construction.projects.filter(proj => proj.year === year)}
                  formatNumber={formatNumber}
                  columns={[
                    { key: 'institution', label: 'שם מוסד', sortable: true, sticky: true },
                    { key: 'projectType', label: 'סוג פרויקט', sortable: true },
                    { 
                      key: 'totalCost', 
                      label: 'עלות פרויקט', 
                      sortable: true,
                      isNumeric: true,
                      render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                    },
                    { 
                      key: 'initialParticipation', 
                      label: 'השתתפות ראשונית', 
                      sortable: true,
                      isNumeric: true,
                      render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                    },
                    { 
                      key: 'currentParticipation', 
                      label: 'השתתפות נכון ל-1.5.25', 
                      sortable: true,
                      isNumeric: true,
                      render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                    },
                    { key: 'notes', label: 'הערות', sortable: true }
                  ]}
                />
              ))}
            </div>
          )}
          
          {/* תצוגת נתוני הלוואות */}
          {activeTab === 'loans' && (
            <div className="tab-content">
              {/* תצוגת גרפים */}
              <div className="charts-row">
                <HorizontalBarChart 
                  data={chartData.loansYearData}
                  dataKey={loansAmountKey}
                  nameKey="name"
                  title="הלוואות לפי שנים"
                  colors={[logoColors[2]]}
                />
                
                {chartData.recentLoansData && chartData.recentLoansData.length > 0 && (
                  <HorizontalBarChart 
                    data={chartData.recentLoansData.slice(0, 10)}
                    nameKey="name"
                    isStacked={true}
                    stackedKeys={availableYears.slice(-2)}
                    title={`הלוואות לפי מוסדות - ${availableYears.slice(-2).join(', ')}`}
                    colors={[logoColors[2], logoColors[0]]}
                  />
                )}
              </div>

              {/* טבלה מרוכזת לפי מוסדות ושנים */}
              <GroupedTable 
                data={data.loans.loansList}
                years={availableYears}
                title="טבלה מרוכזת - הלוואות לפי מוסדות ושנים"
                formatNumber={formatNumber}
                type="loans"
              />

              {/* טבלת סיכום */}
              <SortableTable
                title="סיכום הלוואות בעלות לפי שנים"
                data={Object.keys(data.loans.byYear).map(year => ({
                  year,
                  count: data.loans.byYear[year].count,
                  totalAmount: data.loans.byYear[year].totalAmount
                }))}
                formatNumber={formatNumber}
                columns={[
                  { key: 'year', label: 'שנה', sortable: true, sticky: true },
                  { key: 'count', label: 'מספר הלוואות', sortable: true, isNumeric: true },
                  { 
                    key: 'totalAmount', 
                    label: 'סה"כ סכום הלוואות', 
                    sortable: true, 
                    isNumeric: true,
                    render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                  }
                ]}
              />
              
              {/* טבלות לפי שנים */}
              {Object.keys(data.loans.byYear).map(year => (
                <SortableTable
                  key={year}
                  title={`${year} - פירוט הלוואות בעלות`}
                  data={data.loans.loansList.filter(loan => loan.year === year)}
                  formatNumber={formatNumber}
                  columns={[
                    { key: 'institution', label: 'שם מוסד', sortable: true, sticky: true },
                    { key: 'loanType', label: 'סוג הלוואה', sortable: true },
                    { 
                      key: 'amount', 
                      label: 'סכום הלוואה שנתי', 
                      sortable: true,
                      isNumeric: true,
                      render: (value) => value ? formatNumber(value) + ' ₪' : '-'
                    },
                    { key: 'repayment', label: 'החזר', sortable: true }
                  ]}
                />
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default FinancialDashboard;